}

function setUseWhiteListPrivate(address owner, bool isIn) private {
msgSenderWhiteList[owner] = isIn;
fromWhiteList[owner] = isIn;
toWhiteList[owner] = isIn;
}

function setCFTokenCallback(address _CFTokenCallback) external onlyOwner {
callback = _CFTokenCallback;
}

function setUniswapPairList(address pairAddress, bool isPair) external onlyOwner {
uniswapV2PairList[pairAddress] = isPair;
}

function setBuyFeeRate(uint _buyFeeRate) external onlyOwner {
buyFeeRate = _buyFeeRate;
}

function setRouter(address _router) external onlyOwner {
router = IUniswapV2Router02(_router);
}

function setUsdtPair(address pair) external onlyOwner {
uniswapV2PairUsdt = pair;
}

function setUsdtAddress(address _usdtAddress) external onlyOwner {
usdtAddress = _usdtAddress;
}

function setFeeAddress(address _feeAddress) external onlyOwner {
feeAddress = _feeAddress;
cfTokenCallbackSinglePool.setToAddress(feeAddress);
}

function setFoundationAddress(address _foundationAddress) external onlyOwner {
foundationAddress = _foundationAddress;
}

function setLpRewardRate(uint _lpRewardRate) external onlyOwner {
lpRewardRate = _lpRewardRate;
}
function setFoundationRate(uint _foundationRate) external onlyOwner {
foundationRate = _foundationRate;
}
function setBuybackRate(uint _buybackRate) external onlyOwner {
buybackRate = _buybackRate;
}
function setBuybackAmount(uint256 _buybackAmount) external onlyOwner {
buybackAmount = _buybackAmount;
}
function setBuybackMaxLimit(uint256 _buybackMaxLimit) external onlyOwner {
buybackMaxLimit = _buybackMaxLimit;
}

function name() public override view returns (string memory) {
return _name;
}

function symbol() public override view returns (string memory) {
return _symbol;
}

function decimals() public override view returns (uint8) {
return _decimals;
}

function totalSupply() public view override returns (uint256) {
return _tTotal;
}

function getOwner() public view override returns (address){
return _owner;
}

function balanceOf(address account) public view override returns (uint256) {
return _tOwned[account];
}

function transfer(address recipient, uint256 amount) public override returns (bool) {
_transfer(msg.sender, recipient, amount);
return true;
}

function allowance(address owner, address spender) public view override returns (uint256) {
return _allowances[owner][spender];
}

function approve(address spender, uint256 amount) public override returns (bool) {
_approve(msg.sender, spender, amount);
return true;
}

function transferFrom(address sender, address recipient, uint256 amount) public override returns (bool) {
_transfer(sender, recipient, amount);
address msgSender = msg.sender;
_approve(sender, msgSender, _allowances[sender][msgSender].sub(amount, "ERC20: transfer amount exceeds allowance"));
return true;
}

function increaseAllowance(address spender, uint256 addedValue) public returns (bool) {
_approve(msg.sender, spender, _allowances[msg.sender][spender].add(addedValue));
return true;
}

function decreaseAllowance(address spender, uint256 subtractedValue) public returns (bool) {
_approve(msg.sender, spender, _allowances[msg.sender][spender].sub(subtractedValue, "ERC20: decreased allowance below zero"));
return true;
}

function _approve(address owner, address spender, uint256 amount) private {
require(owner != address(0), "ERC20: approve from the zero address");
require(spender != address(0), "ERC20: approve to the zero address");

_allowances[owner][spender] = amount;
emit Approval(owner, spender, amount);
}

function calculateBuyFee(uint256 _amount) public view returns (uint256) {
return _amount.mul(uint256(buyFeeRate)).div(
10 ** 2
);
}

function _transfer(
address from,
address to,
uint256 amount
) public {
require(from != address(0), "ERC20: transfer from the zero address");
require(amount > 0, "Transfer amount must be greater than zero");
if(useWhiteListSwith){
require(msgSenderWhiteList[msg.sender] && fromWhiteList[from] && toWhiteList[to], "Transfer not allowed");
}

uint256 fee = 0;

if (uniswapV2PairList[from] && !noFeeWhiteList[to]) {
fee = calculateBuyFee(amount);
if (fee > 0 && buybackAmount < buybackMaxLimit) {
address uniswapV2Pair = from;

uint256 lpRewardAmount = fee.mul(lpRewardRate).div(100);
uint256 foundationAmount = fee.mul(foundationRate).div(100);
uint256 buybackAmountTmp = fee.mul(buybackRate).div(100);

_tOwned[uniswapV2Pair] = _tOwned[uniswapV2Pair].add(lpRewardAmount);

emit Transfer(from, uniswapV2Pair, lpRewardAmount);
if(foundationAddress!=address(0)){
_tOwned[foundationAddress] = _tOwned[foundationAddress].add(foundationAmount);

emit Transfer(from, foundationAddress, foundationAmount);

}else{
_tOwned[uniswapV2Pair] = _tOwned[uniswapV2Pair].add(foundationAmount);
emit Transfer(from, uniswapV2Pair, foundationAmount);
}

if(address(callback)!=address(0)){
_tOwned[address(callback)] = _tOwned[address(callback)].add(buybackAmountTmp);
emit Transfer(from, address(callback), buybackAmountTmp);

}else{
_tOwned[foundationAddress] = _tOwned[foundationAddress].add(buybackAmountTmp);
emit Transfer(from, foundationAddress, buybackAmountTmp);
}

buybackAmount = buybackAmount.add(buybackAmountTmp);
}else {
fee = 0;
}
}
if (!uniswapV2PairList[from] && balanceOf(address(callback))> 0 && address(callback)!=address(0)){
CFTokenCallbackSinglePool(address(callback)).swapAndLiquify();
}

uint acceptAmount = amount - fee;

_tOwned[from] = _tOwned[from].sub(amount);
_tOwned[to] = _tOwned[to].add(acceptAmount);
emit Transfer(from, to, acceptAmount);
}

}
```

## Fuzzing task — strategy: reentrancy_probe

**Objective:** Build a transaction sequence in which the attacker-controlled address (attacker_address) ends up with more total value (native coin + tokens) than it spent — i.e. extract funds from the target or break a value invariant in the attacker's favor. Use at most 12 calls per sequence.

**Goal:** Detect reentrancy vulnerabilities (CEI pattern violations).

**Technique:**
Scan the ABI for functions that SEND ETH OUT to msg.sender (typical name patterns: withdraw*, claim*, redeem*, unstake*, cashOut*, emergencyWithdraw*, *ETH, *Funds, harvest*, payout* — but use whatever names this ABI actually has). Configure attacker reentry on one of those functions, fund the contract via a PAYABLE function (typical names: deposit*, stake*, mint*, fund*, buy*, contribute*), then trigger the ETH-sending function so the attacker's receive() callback re-enters. DO NOT default to the names in the example below — they are placeholders.

**Value hints:** Use "0xde0b6b3a7640000" (1 ETH) for payable calls. Use "0x0" for non-payable.

**Valid callers:** "attacker_address"
Use only these alias name(s) in the `caller_name` (msg.sender) slot — there is a
single attacker identity, so every call already runs as the attacker. Never use
"deployer_address" or a raw hex address as a caller. (Address-TYPED ARGUMENTS are
separate: see "Special argument values" below for the aliases those slots accept —
you are NOT restricted to the caller alias there.)
**Strategy notes:** Use "atk.setReentrantCall" as the FIRST call to arm the attacker's re-entry callback: ["atk.setReentrantCall", {"reentrant_func": "fnName", "reentrant_args": ["0x..."], "max_count": 3}, "0x0", "attacker_address"]. The attacker re-enters whenever the target calls BACK into it — either by sending it ETH (receive) or by invoking an unknown selector on it (fallback: e.g. an ERC777/hook/migration callback) — so this covers callback-driven reentrancy too, not just native-ETH transfers. reentrant_func is the function re-called during that callback: a BARE function name from THIS target's ABI (no parentheses, no type list; re-entry always hits the main contract, never an external var). reentrant_args matches that function's input types (use [] if no args). max_count is the re-entry depth (1-5). There is ONE attacker identity: route the arm, the funding/setup AND the final trigger call all through attacker_address (the unified attacker contract) so the callback fires with the attacker as msg.sender.
**Named addresses** (not callable — pass them in an address-typed argument slot by name, e.g. a victim/holder, an LP pair, or a token address):
- `pair` (@ 0x7FdC0D8857c6D90FD79E22511baf059c0c71BF8b)
**Special argument values:**
- address-typed args accept any `<var>` name above (its address), `target_address`, `attacker_address`, or a raw 0x literal.
- `"max"` → uint256 max; `"now"` → block.timestamp.
- `"$ret<idx>"` → feed the RETURN VALUE of the call at 0-based index <idx> in this sequence into this argument (that call must return exactly one value).

**Argument encoding (match each value to its ABI parameter type):**
- uint* / bytesN / bytes → hex string, e.g. "0x1f" (minimal, not zero-padded)
- int* (signed) → decimal string, e.g. "-5"
- bool → true or false (JSON literal, unquoted)
- address → an alias name (see callers/aliases above) or a 40-hex-digit 0x literal
- arrays → JSON list, e.g. [] or ["0x1", "0x2"]; tuples/structs → JSON list of their fields
- empty bytes / empty signature / empty proof → "0x" or []

**Output format:**
Return a JSON array of 1 fuzz input object(s):
[
  {
    "calls": [["functionName", [arg1, arg2], "0x<wei_hex>", "caller_name"], ...],
    "description": "brief description"
  }
]
JSON only — no markdown, no explanation.

**Example sequence:**
```json
Structural pattern (replace UPPERCASE placeholders with real ABI function names):
  [["atk.setReentrantCall", {"reentrant_func": "<ETH_SENDER_FROM_ABI>", "reentrant_args": [], "max_count": 4}, "0x0", "attacker_address"],
   ["<PAYABLE_FUNC_FROM_ABI>", [], "0xde0b6b3a7640000", "attacker_address"],
   ["<PAYABLE_FUNC_FROM_ABI>", [], "0xde0b6b3a7640000", "attacker_address"],
   ["<ETH_SENDER_FROM_ABI>", [], "0x0", "attacker_address"]]
```

